require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/ready_set.json is
# ReadySet.readySet for every Workflow of three Steps (serial or parallel;
# queued and ready, queued and not ready, running, or done) and every cursor,
# generated by `lake exe syrus_fixtures ready_set`. This builds each Workflow
# with real Steps in those states and runs the real
# StepDispatcher#distributed_ready_set from each cursor. Readiness (dependency
# settlement) and parallelism (placement policy plus the DAG flag) are stubbed
# per Step, and no Step is skippable: the model abstracts exactly those three
# predicates, and the scan over them is what it is about.
RSpec.describe "ReadySet model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/ready_set.json").read)
  workflows = fixture.fetch("cases").group_by { |example| example.fetch("steps") }

  it "covers every Workflow of three Step variants and every cursor" do
    expect(workflows.size).to eq(8**3)
    expect(workflows.values.map(&:size).uniq).to eq([ 4 ])
  end

  workflows.each_with_index do |(steps, examples), index|
    label = steps.map { |step| "#{step.fetch('kind')}/#{step.fetch('state')}#{step.fetch('state') == 'queued' ? (step.fetch('ready') ? '/ready' : '/waiting') : ''}" }.join(", ")

    it "picks the model's ready set from every cursor for [#{label}]" do
      workflow = Workflow.create!(job: Factories.job_record(issue_number: 1000 + index), trigger_kind: "initial", state: "running")
      records = steps.each_with_index.map do |step, position|
        Step.create!(workflow: workflow, kind: step.fetch("kind") == "parallel" ? "grader" : "implement",
          position: position, state: step.fetch("state"))
      end
      by_id = records.zip(steps).to_h { |record, step| [ record.id, step ] }

      examples.each do |example|
        cursor = example.fetch("cursor")
        dispatcher = cursor.zero? ? StepDispatcher.new(workflow) : StepDispatcher.new(workflow, advancing_from: records.fetch(cursor - 1))
        allow(dispatcher).to receive(:ready?) { |step| by_id.fetch(step.id).fetch("ready") }
        allow(dispatcher).to receive(:parallel_runnable_step?) { |step| by_id.fetch(step.id).fetch("kind") == "parallel" }
        allow(dispatcher).to receive(:skippable_queued_step?).and_return(false)

        picked = dispatcher.send(:distributed_ready_set).map(&:position)

        expect(picked).to eq(example.fetch("ready_set")), "cursor #{cursor}: ruby #{picked}, model #{example.fetch('ready_set')}"
      end
    end
  end
end
